/* nodes details for region "measurement", loaded on demand by atlas/app.js (ATLAS.loadDetails). */
window.ATLAS.addDetails("measurement.nodes",{"nodes":{
"averaging-leveling":{"description":{"zh":"把平均数看作倒水齐平后的水位：总量守恒，水位 = 总量 ÷ 杯数。假设水可自由倒且可分。","en":"The mean seen as the level after pouring until even: the total is conserved and level = total ÷ cups. Assumes water pours freely and is divisible."},"formula":"mean = total / n","source":"../math/data/averaging-leveling/#step2","lessons":[{"slug":"averaging-leveling","step":2,"category":"math","stage":"primary","primary":true}]},
"bar-charts":{"description":{"zh":"柱高表示数值，可读差、可见纵轴起点如何改变视觉差距，并用平均线补平高出与不足。仅用 8 个示意数据。","en":"Bar height encodes value; read differences, see how the axis start changes apparent gaps, and balance excess against shortfall with a mean line. Uses 8 illustrative values only."},"formula":"mean = Σx / n","source":"../math/data/bar-charts/#step3","lessons":[{"slug":"bar-charts","step":3,"category":"math","stage":"primary","primary":true}]},
"clock-angles":{"description":{"zh":"时针 0.5°/分、分针 6°/分，由相对速度 5.5°/分算出夹角、重合与直角的时刻。仅限理想连续钟。","en":"Hour hand 0.5°/min and minute hand 6°/min give a relative rate of 5.5°/min, from which angles, overlaps and right angles follow. Ideal continuous clock only."},"formula":"θ = |30h + 0.5m − 6m|","source":"../math/geometry/clock-angles/#step1","lessons":[{"slug":"clock-angles","step":1,"category":"math","stage":"primary","primary":true}]},
"density":{"description":{"zh":"密度 ρ = m/V：同种均匀材料的质量与体积成正比，比值只由材料决定；比较密度可判断浮沉，排水法可测不规则物体的体积。仅适用于实心均匀物体和常温常压典型值。","en":"Density ρ = m/V: for one uniform material, mass is proportional to volume and the ratio depends only on the material; comparing densities predicts float or sink, and displacement measures odd-shaped volumes. Valid for solid uniform objects at typical room conditions."},"formula":"ρ = m / V","source":"../physics/matter/density/#step2","lessons":[{"slug":"density","step":2,"category":"physics","stage":"junior","primary":true}]},
"mean-median-mode":{"description":{"zh":"平均数、中位数、众数各回答不同问题；极端值会拉动平均数而几乎不动中位数和众数。数据为示意数据。","en":"Mean, median and mode answer different questions; an extreme value drags the mean but barely moves the median or mode. The data are illustrative."},"formula":"mean = Σx/n","source":"../probability/statistics/mean-median-mode/#step1","lessons":[{"slug":"mean-median-mode","step":1,"category":"probability","stage":"junior","primary":true}]},
"binomial-normal":{"description":{"zh":"由杨辉三角数路径得到二项分布 C(n,k)pᵏ(1−p)ⁿ⁻ᵏ，均值 np、方差 np(1−p)；n 增大时它贴近同均值同标准差的正态曲线，并学习连续性修正。独立、概率固定的二选一模型，近似误差在远尾部较大。","en":"Counting paths in Pascal’s triangle gives the binomial C(n,k)pᵏ(1−p)ⁿ⁻ᵏ with mean np and variance np(1−p); as n grows it hugs the normal curve of the same mean and spread, with a continuity correction for tails. Independent two-way trials with fixed p; the approximation is weakest in far tails."},"formula":"P(k) = C(n,k) pᵏ (1−p)ⁿ⁻ᵏ ≈ N(np, np(1−p))","source":"../probability/basics/binomial-normal/#step3","lessons":[{"slug":"binomial-normal","step":3,"category":"probability","stage":"senior","primary":true}],"note":"Edges use existing atlas nodes probability, gaussian and variance.","aliases":{"zh":["钟形曲线","高尔顿板"],"en":["bell curve","Galton board"]}},
"estimate":{"description":{"zh":"从读数反推真值：终点读数、刻度、重复测量都有误差，所以估计永远是“数值 ± 不确定度”。不确定度不是错误，是诚实标出这把尺子的可信范围；多测几次平均，不确定度随 1/√n 缩小。","en":"Working backwards from readings to the true value: end-point readings, scales and repeats all carry error, so an estimate is always \"value ± uncertainty\". Uncertainty is not a mistake — it honestly marks how far this ruler can be trusted; averaging repeats shrinks it like 1/√n."},"formula":"x̂ = x ± Δx","source":"../chemistry/solutions/titration-curves/#step4","lessons":[{"slug":"titration-curves","step":4,"category":"chemistry","stage":"senior","primary":true}]},
"meiosis":{"description":{"zh":"减数分裂两次分裂、随机取向给出 2ⁿ 种配子、交换与重组率，并与有丝分裂对比；每对最多一次交换的教学模型。","en":"The two meiotic divisions, random alignment giving 2ⁿ gametes, crossing over and recombination frequency, compared with mitosis, in a teaching model with at most one crossover per pair."},"formula":"2ⁿ gamete types","source":"../biology/cells/meiosis/#step2","lessons":[{"slug":"meiosis","step":2,"category":"biology","stage":"senior","primary":true}],"note":"group measurement is the closest of the five atlas groups (randomness and counting); the page is cell biology"},
"natural-selection":{"description":{"zh":"胡椒蛾双色模型：存活率差异、世代递推、优势比决定速度、环境变化的滞后，并与小种群的随机漂变对比；单倍体单基因的教学模型。","en":"A two-colour peppered-moth model: survival differences, generation-by-generation recursion, advantage ratio setting the speed, lag behind a changing environment, and contrast with drift in small populations; a haploid single-gene teaching model."},"formula":"logit p′ = logit p + ln(w_dark/w_light)","source":"../biology/ecology/natural-selection/#step2","lessons":[{"slug":"natural-selection","step":2,"category":"biology","stage":"senior","primary":true}],"note":"group measurement is the closest of the five atlas groups (randomness and estimation); the page is evolutionary biology"},
"probability-distribution":{"description":{"zh":"每个结果的概率排成条形，就是分布：条形高度是 P(X=x)，全部加起来等于 1。条形的重心是期望 E[X]，条形离重心的加权平方距离是方差；右尾的面积回答“至少这么大”的概率。","en":"Probabilities arranged by outcome form a distribution: each bar's height is P(X=x), and all bars sum to 1. The bars' balance point is the expectation E[X]; their probability-weighted squared distance from it is the variance, and the right tail's area answers 'at least this big'."},"formula":"E[X] = Σ x·P(X=x)","source":"../probability/basics/probability-distribution/#step0","lessons":[{"slug":"probability-distribution","step":0,"category":"probability","stage":"senior","primary":true}]},
"regression-correlation":{"description":{"zh":"用相关系数 r 说明点云多贴一条直线，用残差平方和找最小二乘线，并演示离群点与杠杆、混杂因素、非线性关系和回归到平均这几个常见陷阱。全部为种子化模拟数据，假设正态二元分布。","en":"Use the correlation r to say how tightly a cloud follows a line, find the least-squares line by minimising squared residuals, and see the common traps: outliers and leverage, confounders, non-linear relations and regression to the mean. All data are seeded simulations assuming a bivariate normal."},"formula":"r = Σ(x−x̄)(y−ȳ) / √(Σ(x−x̄)²Σ(y−ȳ)²),  m = Σ(x−x̄)(y−ȳ) / Σ(x−x̄)²","source":"../probability/statistics/regression-correlation/#step1","lessons":[{"slug":"regression-correlation","step":1,"category":"probability","stage":"senior","primary":true}]},
"titration-curves":{"description":{"zh":"强酸、弱酸被强碱滴定的 pH 曲线、突跃、半等当点与指示剂选择；理想一元酸模型，忽略活度与 CO₂。","en":"pH curves for strong and weak acids titrated by a strong base: the leap, half equivalence and indicator choice, in an ideal monoprotic model ignoring activity and CO₂."},"formula":"pH = pKₐ at half equivalence","source":"../chemistry/solutions/titration-curves/#step2","lessons":[{"slug":"titration-curves","step":2,"category":"chemistry","stage":"senior","primary":true}]},
"bandit-arms":{"description":{"zh":"概率未知的几台机器，怎样在尝试与利用之间分配有限的拉动次数；比较贪心、ε-贪心、UCB 和汤普森采样的累计遗憾。固定随机种子的模拟，机器设置固定。","en":"With machines of unknown probability, how to split a limited number of pulls between trying and exploiting; compares the cumulative regret of greedy, ε-greedy, UCB and Thompson sampling. Fixed-seed simulations on fixed machine settings."},"formula":"UCB = x̄ᵢ + c·√(2 ln t / nᵢ)","source":"../probability/stochastic/bandit-arms/#step2","lessons":[{"slug":"bandit-arms","step":2,"category":"probability","stage":"university","primary":true}]},
"bayes":{"description":{"zh":"先验是观测前的概率，后验是观测后的更新。似然描述给定假设下观测如何出现；本页离散例子中是观测概率。把它与先验结合并归一化，得到依赖观测模型的后验。","en":"A prior is a probability before evidence; a posterior is its update afterward. Likelihood describes evidence under a hypothesis—in this lesson’s discrete examples it is an observation probability. Combine it with the prior and normalize; the result depends on the observation model."},"formula":"posterior ∝ likelihood × prior","source":"../probability/inference/bayes-updating/#step1","lessons":[{"slug":"bayes-updating","step":1,"category":"probability","stage":"university","primary":true}]},
"decision-trees":{"description":{"zh":"像玩“二十问”：用熵衡量一堆样本有多混乱，每刀选信息增益最大的切法，让混乱下降最快，贪心地长成一棵树；但贪心只看眼前一步，不保证全局最少问题，所以要用深度限制它，别把噪声也学进去。数据是人造的二维两类点。","en":"Like twenty questions: entropy measures how mixed a pile of samples is, each cut picks the largest information gain so disorder falls fastest, and the tree grows greedily. But greedy looks only one step ahead and does not guarantee the fewest questions overall, so depth limits stop it from learning noise. The data are artificial 2-D two-class points."},"formula":"IG = H(parent) − Σ (nₖ/n)·H(childₖ)","source":"../computing/ml/decision-trees/#step1","lessons":[{"slug":"decision-trees","step":1,"category":"computing","stage":"university","primary":true}]},
"gaussian":{"description":{"zh":"独立同分布、方差有限且非零时，样本均值经过适当标准化后，随样本量增加趋于标准正态分布。","en":"For iid samples with finite, nonzero variance, the appropriately standardized sample mean approaches a standard normal distribution as sample size grows."},"formula":"SE(mean) = σ / √n","source":"../probability/statistics/central-limit-theorem/#step3","lessons":[{"slug":"central-limit-theorem","step":3,"category":"probability","stage":"university","primary":true}],"aliases":{"zh":["正态分布","钟形曲线","高斯分布","中心极限定理"],"en":["normal distribution","bell curve","Gaussian distribution","central limit theorem"]}},
"hypothesis-testing":{"description":{"zh":"以抛硬币为例：p 值是零假设为真时出现至少同样极端结果的概率；α 是第一类错误的预算，功效 1 − β 随效应与样本量上升；同时做多次检验总会碰到“显著”，需要校正。精确二项检验模型，p 值不是假设为真的概率。","en":"With coin flips: the p-value is the probability, if the null is true, of a result at least as extreme; α is the budget for type I errors, power 1 − β grows with effect and sample size, and running many tests always turns up something “significant”, so corrections are needed. An exact binomial test model; a p-value is not the probability that the hypothesis is true."},"formula":"p = P(result at least as extreme | H₀)","source":"../probability/inference/hypothesis-testing/#step0","lessons":[{"slug":"hypothesis-testing","step":0,"category":"probability","stage":"university","primary":true}],"note":"Uses the atlas uncertainty group. Edges use the atlas nodes bayes and probability."},
"kalman":{"description":{"zh":"先用动态模型预测状态，再根据测量及其不确定性修正。协方差表示模型估计的不确定性，并不保证真实误差同样小。","en":"Predict a state with a dynamic model, then correct it using measurements and their uncertainty. Covariance describes model uncertainty, not guaranteed real-world error."},"formula":"predict → correct","source":"../signal/control/kalman/#step2","lessons":[{"slug":"kalman","step":2,"category":"signal","stage":"university","primary":true}]},
"llm-sampling":{"description":{"zh":"每一步把分数用 softmax 变成概率，用温度整形，用 top-k / top-p 截断，再随机抽一个词。分数是手工设定的玩具数据，不是真实模型输出。","en":"At each step scores become probabilities via softmax, temperature reshapes them, top-k / top-p trim the tail and one word is drawn at random. Scores are hand-set toy data, not real model outputs."},"formula":"p_i ∝ exp(z_i / T)","source":"../computing/ml/llm-sampling/#step1","lessons":[{"slug":"llm-sampling","step":1,"category":"computing","stage":"university","primary":true}]},
"markov-chains":{"description":{"zh":"下一步只取决于当前状态；n 步转移是转移矩阵的 n 次幂；正常的链收敛到稳态 π（πP = π），速度由第二特征值 |λ₂| 决定；有吸收态的链（赌徒）没有中间稳态。有限状态、一阶、时间齐次模型。","en":"The next step depends only on the current state; n-step transitions are the n-th power of the transition matrix; an ordinary chain converges to a steady state π (πP = π) at a speed set by the second eigenvalue |λ₂|; a chain with absorbing states (the gambler) has no middle steady state. A finite, first-order, time-homogeneous model."},"formula":"πP = π","source":"../probability/stochastic/markov-chains/#step3","lessons":[{"slug":"markov-chains","step":3,"category":"probability","stage":"university","primary":true}],"note":"Uses the atlas uncertainty group. Edges use atlas nodes probability and eigen."},
"montecarlo":{"description":{"zh":"通过随机样本的平均估计期望或积分：扔 1 万次飞镖估圆面积就是它。误差大小依赖采样方式、样本量及被估计量的方差；样本 ×4、误差大约 ÷2。","en":"Estimate expectations or integrals from random-sample averages: throwing 10,000 darts to estimate a circle's area is exactly this. Error depends on sampling, sample count and the variance of the quantity estimated; four times the samples roughly halves the error."},"formula":"estimate = sample average","source":"../probability/stochastic/monte-carlo/#step3","lessons":[{"slug":"monte-carlo","step":3,"category":"probability","stage":"university","primary":true}]},
"overfitting":{"description":{"zh":"用多项式拟合带噪声的点：训练误差随灵活度单调下降，测试误差先降后升；数据量、换批数据和岭回归如何改变它。数据与种子固定，是教学演示。","en":"Fit noisy points with polynomials: training error falls monotonically with flexibility while test error falls then rises; how data size, resampling and ridge regression change this. Fixed data and seeds make it a teaching demonstration."},"formula":"minimise Σ(yᵢ − f(xᵢ))² + λ‖w‖²","source":"../computing/ml/overfitting/#step1","lessons":[{"slug":"overfitting","step":1,"category":"computing","stage":"university","primary":true}]},
"poisson-process":{"description":{"zh":"用种子可重复的模拟看恒定平均速率下的随机到达：间隔服从指数分布、窗口内个数服从泊松分布，指数分布无记忆，独立泊松流合并与稀释后仍是泊松；并用散度比判断一组数据是否像泊松。速率恒定、到达独立的模型。","en":"Seeded, repeatable simulations of random arrivals at a constant average rate: gaps are exponential, counts per window are Poisson, the exponential is memoryless, independent Poisson streams stay Poisson when merged or thinned, and a dispersion ratio tests whether data looks Poisson. Constant rate, independent arrivals."},"formula":"P(k) = e^{−λw}(λw)^k / k!","source":"../probability/stochastic/poisson-process/#step2","lessons":[{"slug":"poisson-process","step":2,"category":"probability","stage":"university","primary":true}]},
"probability":{"description":{"zh":"用概率描述可能结果及其不确定性：扔 100 次硬币大约 50 次正面，但单次扔出什么仍不可预测——概率说的是长期频率，不是单次的保证；模型里的概率还要拿观察证据来检验，不能混为一谈。","en":"Use probabilities to describe possible outcomes and uncertainty: 100 coin flips land heads about 50 times, yet a single flip stays unpredictable — probability speaks of long-run frequency, not a guarantee for one trial. Model probabilities must still be checked against observed evidence, never confused with it."},"formula":"0 ≤ P(A) ≤ 1","source":"../probability/inference/bayes-updating/#step0","lessons":[{"slug":"bayes-updating","step":0,"category":"probability","stage":"university","primary":true}]},
"risk-pooling":{"description":{"zh":"从个人 0 或 10000 元的赌局出发，看人数增加时人均损失的波动按 1/√N 缩小，用精确二项分布算保费与破产概率；再展示共同灾难使波动停在下限、逆向选择使保费螺旋上升，以及所需准备金。模拟与精确计算结合，不是真实保险数据。","en":"From one person’s $0-or-$10,000 gamble, see the spread of average loss shrink as 1/√N as the pool grows, price premiums and ruin with the exact binomial, then see a shared disaster stop the spread at a floor, adverse selection spiral the premium, and the reserves needed. A mix of simulation and exact calculation, not real insurance data."},"formula":"SD(平均损失) = L·√(p(1−p)/N)","source":"../probability/stochastic/risk-pooling/#step1","lessons":[{"slug":"risk-pooling","step":1,"category":"probability","stage":"university","primary":true}]},
"variance":{"description":{"zh":"与均值的偏差平方的期望，用于描述分散程度：平方既消掉正负号，又让偏离大的点代价更大；但单位也成了原单位的平方，所以实用时常开方回到原单位，那就是标准差。","en":"The expected squared deviation from the mean, measuring spread: squaring removes the sign and punishes large misses more, but it also squares the units — so in practice we take the square root back to the original units, which is the standard deviation."},"formula":"Var(X) = E[(X−μ)²]","source":"../probability/statistics/central-limit-theorem/#step3","lessons":[{"slug":"central-limit-theorem","step":3,"category":"probability","stage":"university","primary":true}]}
}});
